+// RF-005, ADR-002: anula una factura emitida. Devuelve una factura nueva en estado "anulada"; la original no se toca.
+export function anularFactura(factura, motivo) {
+  if (!factura || factura.estado !== "emitida") throw new Error("Solo se puede anular una factura emitida");
+  if (typeof motivo !== "string" || motivo.trim() === "") throw new Error("El motivo de anulación es obligatorio");
+  return Object.freeze({ ...factura, estado: "anulada", motivoAnulacion: motivo.trim() });
+}
